let S=fresh();try{let d=JSON.parse(localStorage.getItem(KEY)||'null');if(d&&d.v&&d.items&&d.records)S=Object.assign(fresh(),d)}catch(e){}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};
