const flash=(msg,isBad=false)=>{if(isBad&&S.mode==='exam'&&S.scenarioStarted){S.examMistakes=(S.examMistakes||0)+1;save()}const x=document.getElementById('toast');x.textContent=msg;x.style.display='block';x.style.borderColor=isBad?'#c88988':'#baa65e';document.getElementById('statusText').textContent=msg;clearTimeout(flash._id);flash._id=setTimeout(()=>x.style.display='none',3200)};
const dataHelp=(title,txt)=>' data-help="'+h(title+(txt?' — '+txt:''))+'"';
const btn=(text,act,help,cls='')=>'<button type="button" class="btn '+cls+'" data-action="'+act+'" '+dataHelp(text,help)+'>'+text+'</button>';
const iconbtn=(text,act,help)=>btn(text,act,help,'btn-icon');
function entry(doc,key,help,ph='',type='text',extra=''){
 let x=v(doc)[key]||'';
 return '<input class="entry" type="'+type+'" data-field="'+doc+'.'+key+'" value="'+h(x)+'" placeholder="'+h(ph)+'" '+dataHelp(FIELD_LABELS[key]||key,help)+' '+extra+'>';
}
function ref(doc,key,ds,help,placeholder=''){
 return '<div class="reference" '+dataHelp(FIELD_LABELS[key]||key,help)+'>'+entry(doc,key,help,placeholder)+'<button class="ref-action" data-choose="'+ds+'" data-target="'+doc+'.'+key+'" '+dataHelp('Выбрать из справочника',help)+' title="Выбрать из справочника">…</button><button class="ref-action" data-clear="'+doc+'.'+key+'" title="Очистить значение" '+dataHelp('Очистить значение','Удаляет выбор из документа, но не запись из справочника.')+'>×</button><button class="ref-action" data-choose="'+ds+'" data-target="'+doc+'.'+key+'" title="Показать все" '+dataHelp('Показать все','Открывает полный список учебного справочника.')+'>▣</button></div>';
}
function field(doc,key,label,help,options={}){
 const control=options.ref?ref(doc,key,options.ref,help,options.placeholder||''):options.select?select(doc,key,options.select,help):options.area?'<textarea class="area" data-field="'+doc+'.'+key+'" '+dataHelp(label,help)+' placeholder="'+h(options.placeholder||'')+'">'+h(v(doc)[key]||'')+'</textarea>':entry(doc,key,help,options.placeholder||'',options.type||'text',options.extra||'');
 return '<div class="field" '+dataHelp(label,help)+'><label for="'+doc+'-'+key+'">'+label+':</label><div class="control">'+control+'</div></div>';
}
function select(doc,key,values,help){return '<select class="select1c" data-field="'+doc+'.'+key+'" '+dataHelp(FIELD_LABELS[key]||key,help)+'>'+['',...values].map(x=>'<option value="'+h(x)+'" '+((v(doc)[key]||'')===x?'selected':'')+'>'+h(x||'— Выберите значение —')+'</option>').join('')+'</select>'}
function check(doc,key,label,help){return '<label class="checkline" '+dataHelp(label,help)+'><input type="checkbox" data-field="'+doc+'.'+key+'" '+(v(doc)[key]?'checked':'')+'> '+label+'</label>'}
function area(doc,key,help,rows=4){return '<textarea class="area" rows="'+rows+'" data-field="'+doc+'.'+key+'" '+dataHelp(FIELD_LABELS[key]||key,help)+'>'+h(v(doc)[key]||'')+'</textarea>'}
function header(title,desc){return '<div class="form-caption"><span class="star">☆</span>'+h(title)+(desc?'<span class="muted-caption">'+h(desc)+'</span>':'')+'</div>'}
function toolbar(buttons){return '<div class="toolbar">'+buttons+'</div>'}
function tabs(active,arr,group){return '<div class="form-tabs">'+arr.map(([id,title])=>'<button class="form-tab '+(active===id?'active':'')+'" data-tab="'+group+'.'+id+'" '+dataHelp(title,'Вкладка формы 1С. Переключает соответствующий раздел, не очищая введённые данные.')+'>'+h(title)+'</button>').join('')+'</div>'}
function subtabs(active,arr,group){return '<div class="surface-tabs">'+arr.map(([id,title])=>'<button class="'+(id===active?'active':'')+'" data-tab="'+group+'.'+id+'" '+dataHelp(title,'Вкладка табличной части или дополнительных реквизитов документа.')+'>'+h(title)+'</button>').join('')+'</div>'}
const tab=(group,def)=>S.activeTab[group]||def;
function trow(cells,callback){return '<tr '+(callback?'data-row="'+h(callback)+'"':'')+'>'+cells.map(y=>'<td>'+y+'</td>').join('')+'</tr>'}
function table(headers,rows,empty='Нет записей',opts=''){
 let inner='<table class="table1c" '+opts+'><thead><tr>'+headers.map(x=>'<th '+dataHelp(x,'Столбец таблицы 1С. Для выбора записи выделите строку или откройте её двойным щелчком.')+'>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table>';
 return inner+(!rows.length?'<div class="table-empty">'+h(empty)+'</div>':'');
}
function info(msg,cls=''){return '<div class="feedback '+cls+'">'+msg+'</div>'}
function persistAction(action){setFlag(action);save();refreshGuide()}
function toolbarBasic(doc,saveCaption='Записать и закрыть'){return toolbar(btn(saveCaption,'save:'+doc,'Записывает учебный документ. Проверяются обязательные поля.','btn-primary')+btn('▣','saveDraft:'+doc,'Сохраняет текущие поля без проведения документа.')+btn('Отмена','cancel:'+doc,'Возврат на рабочий стол без удаления введённых значений.')+btn('Еще ▾','more:'+doc,'Дополнительные команды учебного документа.'))}
function applyElementHelps(root){if(!root)return;root.querySelectorAll('button,input,select,textarea,a,th,label,tbody tr').forEach(el=>{if(el.dataset.help||el.closest('[data-help]'))return;const text=(el.getAttribute('aria-label')||el.getAttribute('title')||el.textContent||el.getAttribute('placeholder')||'Элемент интерфейса').trim().slice(0,85);const field=el.dataset.field?.split('.')[1],name=FIELD_LABELS[field]||text;if(el.matches('button,a'))el.dataset.help=name+' — Нажмите для выполнения соответствующей команды. В учебной базе изменения не влияют на 1С.';else if(el.matches('input,textarea,select'))el.dataset.help=name+' — Заполните значение самостоятельно или выберите его из списка.';else if(el.matches('tr'))el.dataset.help='Строка справочника — Щелкните для выделения, двойной щелчок открывает существующую учебную карточку.';else el.dataset.help=name+' — Поле или колонка формы 1С. Откройте сценарий, чтобы узнать порядок работы.'})}
function paint(){const screen=document.getElementById('screen');screen.innerHTML=renderScreen();applyElementHelps(screen);document.getElementById('openTab').childNodes[0].textContent='▣ '+names[S.screen]+' ';document.querySelectorAll('#topNav button[data-nav]').forEach(x=>x.classList.toggle('on',x.dataset.nav===S.screen));document.getElementById('app').classList.toggle('exam-mode',S.mode==='exam');document.getElementById('app').classList.toggle('only-1c',!!S.only1c);document.getElementById('viewSwitch').textContent=S.only1c?'Вернуть панель обучения':'Вид только формы 1С';const modeButton=document.getElementById('modeSwitch');modeButton.textContent=S.mode==='exam'?'◉ Экзамен':'◉ Обучение';modeButton.classList.toggle('is-exam',S.mode==='exam');refreshGuide();updateRibbon();save()}
function updateRibbon(){const r=document.getElementById('trainingRibbon');if(!r)return;const current=SCENARIOS.find(x=>x.id===S.scenario),task=document.getElementById('ribbonTask'),title=document.getElementById('ribbonTitle'),pr=document.getElementById('ribbonProgress'),hb=document.getElementById('ribbonHelp');r.classList.toggle('ribbon-idle',!current);if(!current){title.textContent=S.mode==='exam'?'Экзамен: выберите задание':'Свободное изучение';task.textContent=S.mode==='exam'?'Откройте «Сценарии» и выберите экзаменационное задание.':'Открывайте формы и наводите курсор на любой элемент для объяснения.';pr.style.width='0%'}else{const total=current.steps.length,passed=current.steps.filter(x=>x.test()).length;title.textContent=(S.mode==='exam'?'Экзамен: ':'Сценарий: ')+current.title;task.textContent=S.mode==='exam'?'Выполните задание самостоятельно. Ошибки фиксируются.':(current.steps[passed]?.desc||current.steps[passed]?.label||'Задание выполнено.');pr.style.width=Math.round(100*passed/total)+'%'}hb.style.display=S.mode==='exam'?'none':'';document.getElementById('startHelp').disabled=S.mode==='exam';document.getElementById('helpTopic').style.display=S.mode==='exam'?'none':''}
function renderScreen(){switch(S.screen){case'desktop':return screenDesktop();case'event':return screenEvent();case'task':return screenTask();case'contacts':return screenList('counterparties');case'counterparty':return screenCounterparty();case'vehicles':return screenList('vehicles');case'vehicle':return screenVehicle();case'estimate':return screenEstimate();case'repair':return screenRepair();case'express':return screenExpress();case'max':return screenMax();case'blocked':return screenBlocked();case'email':return screenEmail();case'appointment':return screenAppointment();case'tasks':return screenTaskQueue();case'progress':return screenProgress();default:return screenDesktop()}}
function go(x){if(!names[x])return;if(x==='task')S.activeTaskId=null;S.screen=x;document.getElementById('app')?.classList.remove('drawer-left');paint()}
function buildNav(){document.getElementById('docNav').innerHTML=navDocs.map(x=>'<button data-nav="'+x+'" class="'+(S.screen===x?'selected':'')+'" '+dataHelp(names[x],helper[x]||'Открыть соответствующий рабочий документ.')+'>'+h(names[x])+'</button>').join('');document.getElementById('scenarioList').innerHTML='<div class="scenario-nav">'+SCENARIOS.map(s=>'<button data-scenario="'+s.id+'" class="'+(S.scenario===s.id?'selected':'')+'" '+dataHelp(s.title,s.description)+'>'+h(s.title)+'<div class="mini">'+h(names[s.doc])+'</div></button>').join('')+'</div>'}
function refreshGuide(){buildNav();const s=SCENARIOS.find(x=>x.id===S.scenario);const root=document.getElementById('scenarioCard');if(!s){root.innerHTML='<p class="tiny-note">Сценарий не выбран. Откройте документ или выберите последовательность работы в левой панели.</p>';return}let done=0;for(let i=0;i<s.steps.length;i++){if(s.steps[i].test())done++;else break}let next=s.steps[done];S.step=done;if(S.mode==='exam'){root.innerHTML='<h3>'+h(s.title)+'</h3><p>'+h(s.description)+'</p><p>Ошибки: '+(S.examMistakes||0)+'. Подсказки отключены.</p><p>Выполняйте действия самостоятельно на форме 1С.</p>';updateRibbon();save();return}root.innerHTML='<h3>'+h(s.title)+'</h3><p>'+h(s.description)+'</p><div class="scenario-progress"><div style="width:'+Math.round(100*done/s.steps.length)+'%"></div></div><p><b>'+done+' / '+s.steps.length+'</b> шагов выполнено</p>'+s.steps.map((x,i)=>'<div class="scenario-step '+(i<done?'done':i===done?'active':'')+'"><strong>'+(i<done?'✓ ':i===done?'▸ ':'')+(i+1)+'. '+h(x.label)+'</strong>'+(i===done?'<span>'+h(x.desc||'Выполните действие в рабочей форме.')+'</span>':'')+'</div>').join('')+(next?btn('Открыть нужную форму','goto:'+s.doc,'Открыть документ, в котором выполняется активный шаг.'):'<div class="feedback good">Все шаги выполнены. Можете повторить сценарий или начать следующий.</div>');updateRibbon();save()}
function showHelp(text,heading='Объект интерфейса 1С'){document.getElementById('helpTopic').innerHTML='<strong>'+h(heading)+'</strong><p>'+h(text)+'</p><p class="tiny-note">Для тренировки используйте настоящее поле или кнопку на форме.</p>'}
function startScenario(id){const s=SCENARIOS.find(x=>x.id===id);if(!s)return;S.scenario=id;S.step=0;S.scenarioStarted=true;S.examMistakes=0;S.helpCount=0;delete S.flags['scenarioDone:'+S.mode+':'+id];document.getElementById('app').classList.remove('drawer-left','drawer-right');S.screen=s.doc;S.v[s.doc]=fresh().v[s.doc]||{};if(id==='event-call'){S.v.event.kind='Входящий звонок';S.v.event.phone='79000002001'}if(id==='event-meet'){S.v.event.kind='Встреча'}if(s.doc==='estimate'){S.items={works:[],parts:[]};delete S.flags.kpCoordination;}delete S.flags['save:'+s.doc];delete S.flags['taskCreated'];delete S.flags['appointmentCreated'];delete S.flags['emailSimulated'];delete S.flags['maxInvited'];delete S.flags['blockedRequested'];delete S.flags['blockedApproved'];paint();flash('Сценарий начат: '+s.title)}
function chooseRecord(ds,target,customFilter=null){const allRecords=(datasets[ds]||[]).concat(S.records[ds]||[]);const rows=customFilter?allRecords.filter(customFilter):allRecords;const titles={contacts:'Контактные лица',counterparties:'Контрагенты',vehicles:'Автомобили',brand:'Марки автомобилей',model:'Модели автомобилей',spec:'Варианты комплектации',works:'Автоработы',parts:'Номенклатура товаров',groups:'Группы пользователей',documents:'Документы'};
 const heads={contacts:['Контактное лицо','Телефон','Владелец'],counterparties:['Наименование','ИНН','Договор'],vehicles:['Автомобиль','VIN','Гос. номер'],works:['Код','Авторабота'],parts:['Артикул','Номенклатура']};
 const cols=r=>({contacts:[r.name,r.phone,r.owner],counterparties:[r.name,r.inn,r.agreement],vehicles:[r.name,r.vin,r.plate],works:[r.code,r.name],parts:[r.code,r.name]}[ds]||[r.name,r.code||'',r.spec||'']);
 let all=(heads[ds]||['Наименование','Код','Примечание']);
 modal('<span>Выбор: '+h(titles[ds]||ds)+'</span>','<div class="modal-search"><input id="modalSearch" placeholder="Поиск по наименованию, ИНН, VIN, телефону..." autofocus><button class="btn" data-modal-search="1">Найти</button></div><div class="tiny-note">Двойной щелчок или кнопка «Выбрать» переносит значение в поле документа. Пока запись не выбрана, поле остаётся пустым.</div><div id="pickerRows">'+table(all,rows.map(r=>trow(cols(r).map(h),'pick:'+ds+':'+r.id)))+'</div>',btn('Выбрать','pickSelected','Заполнить поле выбранной записью.','btn-primary')+btn('Отмена','closeModal','Закрыть окно без выбора.'));
 window._pick={ds,target,rows,cols,heads:all,selected:null};
}
function bulkRows(type,records){return '<div class="bulk-pick">'+records.map(r=>'<label class="bulk-row" '+dataHelp(r.name,'Позиция учебного справочника. Установите флажок для включения в подбор.')+'><input type="checkbox" data-bulk="'+h(r.id)+'" '+(window._bulk?.selected?.has(r.id)?'checked':'')+'><span class="bulk-code">'+h(r.code)+'</span><span>'+h(r.name)+'</span></label>').join('')+'</div>'}
function modal(title,body,buttons){document.getElementById('modalLayer').innerHTML='<div class="modal" role="dialog" aria-modal="true"><div class="modal-head">'+title+'<button data-action="closeModal" title="Закрыть">×</button></div><div class="modal-body">'+body+'</div><div class="modal-actions">'+buttons+'</div></div>';applyElementHelps(document.getElementById('modalLayer'));document.getElementById('modalLayer').querySelector('input')?.focus()}
function closeModal(){document.getElementById('modalLayer').innerHTML='';window._pick=null}
function pick(){let x=window._pick;if(!x||!x.selected){flash('Выберите строку из справочника',true);return}let r=x.rows.find(r=>r.id===x.selected);if(!r)return;let [doc,key]=x.target.split('.');if(doc==='estimate'&&(key==='workNew'||key==='partNew')){let type=key==='workNew'?'works':'parts';S.items[type].push({name:r.name,code:r.code||'',quantity:'',price:'',agreed:false})}else{v(doc)[key]=r.name}if(x.ds==='contacts'){v(doc).phone=r.phone;v(doc).counterparty=r.owner;let p=datasets.counterparties.find(x=>x.name===r.owner);if(p)v(doc).agreement=p.agreement}if(x.ds==='counterparties'){let p=datasets.counterparties.find(x=>x.name===r.name);if(p){v(doc).inn=p.inn;if(doc==='event'||doc==='estimate'||doc==='repair'||doc==='task')v(doc).agreement=p.agreement}}if(x.ds==='vehicles'){v(doc).vin=r.vin;v(doc).brand=r.brand;v(doc).model=r.model;v(doc).spec=r.spec}if(x.ds==='contacts'&&r.email)v(doc).email=r.email;if(x.ds==='counterparties'&&doc==='estimate'){v(doc).payer=r.name;}closeModal();paint();flash('Выбрано из справочника: '+r.name)}
function saveRecord(doc){let f=v(doc),errors=[];if(doc==='event'){if(!f.contact)errors.push('Контактное лицо');if(!String(f.agreementText||'').trim())errors.push('Договорённость с клиентом');if(!flag('eventContinued')&&!flag('taskCreated')&&!flag('appointmentCreated')&&!flag('eventCancelled'))errors.push('Следующее действие по обращению');}
if(doc==='task'){if(!f.responsible)errors.push('Ответственный');if(!f.content?.trim())errors.push('Содержание');if(!f.endDate)errors.push('Срок завершения');if(koMode()&&!f.general){if(!f.proposedDate||!f.desiredDate)errors.push('Обе даты записи');else{let now=dateISO(new Date());if(f.proposedDate.slice(0,10)<now||f.desiredDate.slice(0,10)<now||f.proposedDate.slice(0,10)>plus(new Date(),60)||f.desiredDate.slice(0,10)>plus(new Date(),60))errors.push('Даты вне периода 0–60 дней')}}}
if(doc==='counterparty'){if(!f.name||!f.inn)errors.push('Наименование и ИНН')}
if(doc==='vehicle'){if(!f.brand||!f.model||!f.vin)errors.push('Марка, модель и VIN');if(f.vin&&!/^[A-HJ-NPR-Z0-9]{17}$/.test(String(f.vin)))errors.push('VIN: 17 символов латиницей без I, O и Q');if(f.year&&f.year>dateISO(new Date()))errors.push('Дата выпуска не может быть в будущем');if(!f.plate||!f.color)errors.push('Госномер и цвет')}
if(doc==='estimate'){if(!f.counterparty||!f.agreement||!f.vehicle||!f.payment)errors.push('Контрагент, договор, автомобиль, способ оплаты');if(!S.items.works.concat(S.items.parts).some(r=>String(r.name||'').trim()&&Number(r.quantity)>0))errors.push('Хотя бы одна работа или запасная часть с количеством')}
if(doc==='appointment'){if(!f.contact||!f.vehicle||!f.date||!f.time||!String(f.reason||'').trim())errors.push('Контакт, автомобиль, дата, время, причина визита');if(f.date&&f.date<dateISO(new Date()))errors.push('Дата визита в прошлом')}
if(doc==='repair'){if(!f.counterparty||!f.vehicle||!f.type)errors.push('Заказчик, автомобиль и вид ремонта');if(!(S.records.repairRows||[]).some(x=>x.name&&Number(x.quantity)>0))errors.push('Не менее одной автоработы с количеством')}
if(errors.length){flash('Не заполнено: '+errors.join('; '),true);return false}
if(doc==='task'&&koMode()&&!f.general&&f.proposedDate&&f.desiredDate){
  const stampDates='Дата записи предлагаемая: '+f.proposedDate.replace('T',' ')+'; дата записи желаемая: '+f.desiredDate.replace('T',' ')+'.';
  if(!String(f.content||'').includes('Дата записи предлагаемая:'))f.content=String(f.content||'').trim()+'\n'+stampDates;
}
if(doc==='appointment'){
 S.records.appointments=S.records.appointments||[];
 const num=f._recordNum||'ЗР-'+String(S.records.appointments.length+1).padStart(5,'0');
 f._recordNum=num;
 const item=Object.assign({no:num},f);
 const index=S.records.appointments.findIndex(x=>x.no===num);
 if(index>=0)S.records.appointments[index]=item;else S.records.appointments.push(item);
}
if(doc==='estimate'){
 S.records.estimates=S.records.estimates||[];
 const no=f._recordNum||'КП-'+String(S.records.estimates.length+1).padStart(5,'0');
 f._recordNum=no;
 const record={no,date:localDate(dateISO(TODAY)),status:f.status||'Подготовка',client:f.counterparty,vehicle:f.vehicle};
 S.records.recommendations=S.records.recommendations||[];
 const recommended=[...S.items.works,...S.items.parts].filter(r=>r.recommended&&r.name).map(r=>({code:r.code,name:r.name,quantity:r.quantity,vehicle:f.vehicle,source:no}));
 S.records.recommendations=S.records.recommendations.filter(r=>r.source!==no).concat(recommended);

 const idx=S.records.estimates.findIndex(x=>x.no===no);
 if(idx<0)S.records.estimates.push(record);else S.records.estimates[idx]=record;
 // v5: workflowOnQuoteSave() coordinates preparation and agreement tasks after successful save.
}
if(doc==='estimate'){workflowOnQuoteSave();const aq=(S.records.autoQuotes||[]).find(q=>q.no===v('estimate')._recordNum);if(aq)aq.stage=v('estimate').status||aq.stage;}
 if(doc==='task'){if(flag('taskPrepared'))setFlag('taskCreated');const ft=v('task');if(!ft._queueTaskId){const newTask=newCRMTask({title:ft.theme||ft.subject||'Задача CRM',kind:ft.type==='Телефонный звонок'?'phone':'manual',assignee:ft.responsible,reference:ft.subject||'Событие',doc:'Событие',content:ft.content,deadline:ft.endDate});ft._queueTaskId=newTask.id;}else{const original=crmQueue().find(x=>x.id===ft._queueTaskId);if(original){original.content=ft.content;original.deadline=ft.endDate;}}}
 setFlag('saved:'+doc);if(doc==='event')setFlag('eventContinued');if(doc==='counterparty'&&!S.records.counterparties.some(r=>r.inn===f.inn))S.records.counterparties.push({id:'u'+Date.now(),name:f.name,inn:f.inn,agreement:'Учебный договор'});if(doc==='vehicle'&&!S.records.vehicles.some(r=>r.vin===f.vin))S.records.vehicles.push({id:'u'+Date.now(),name:f.brand+' '+f.model,vin:f.vin,plate:f.plate||'',brand:f.brand,model:f.model,spec:f.spec||''});save();flash('Учебный документ сохранён: '+names[doc]);paint();return true}
function koMode(){let x=v('task');return /КО/.test(x.responsible||'')&&x.type==='Телефонный звонок'&&x.theme==='Телефонный звонок клиенту'}
function crmQueue(){return S.records.crmTasks||(S.records.crmTasks=[])}
function newCRMTask({title,kind='manual',assignee='Приёмка',reference='',doc='Событие',content='',defectKey='',quoteNo='',deadline=''}){
 const task={id:'crm-'+String(Date.now())+'-'+String(S.taskSeq=(S.taskSeq||0)+1),title,kind,assignee,reference,doc,content,defectKey,quoteNo,deadline,status:'Новая',created:stamp(),result:''};
 crmQueue().push(task);save();return task;
}
function statusActive(t){return !['Выполнена','Отменена','Передано на проценку'].includes(t.status)}
function taskStatusLabel(t){return t.status==='Новая'?'Не принята':t.status}
function taskCard(t){return `<div class="desk-card crm-task-card" data-action="openQueueTask:${h(t.id)}" ${dataHelp(t.title,'Откройте задачу. Если она назначена группе, примите к исполнению, затем выполните действие и запишите результат.')}><strong>▣ ${h(t.title)}</strong><small>Ответственный: ${h(t.assignee)} · ${h(taskStatusLabel(t))}</small><small>${h(t.reference||'Без документа-основания')}</small></div>`}
function screenDesktop(){
 const tasks=crmQueue().filter(statusActive),unread=tasks.filter(t=>t.status==='Новая'),visits=(S.records.appointments||[]).filter(x=>x.status!=='Отменено');
 const intakeTasks=tasks.filter(t=>t.doc==='Событие');const appointmentTasks=tasks.filter(t=>t.doc==='Запись');const dealTasks=tasks.filter(t=>t.doc==='КП');const preparing=tasks.filter(t=>t.status!=='Новая');
 return header('Рабочий стол первой линии CRM')+
 toolbar(btn('⊕ Создать событие','new:event','Создать вручную обращение «Встреча».','btn-primary')+btn('Ответственные','responsibles','Выберите пользователей для текущего рабочего стола.')+btn('▣ Задачи CRM','goto:tasks','Посмотреть все учебные задачи.')+btn('Учебное событие: дефектовка','simulateDefect','Только в тренажёре: имитация системного сообщения о завершении дефектовки. Такой кнопки в 1С может не быть.','sim-only')+btn('↻','refresh','Обновить текущие учебные данные.'))+
 `<div class="status-strip">Отбор: <b>${flag('responsibles')?'Мастер-приёмщик учебный, Приёмка':'Все ответственные'}</b>　 |　 Задачи не приняты: ${unread.length}　 |　 В работе: ${preparing.length}　 |　 Записи: ${visits.length}</div>`+
 `<div class="desktop-layout"><section class="desk-column"><h3 class="red">Не разобранное　${intakeTasks.length+1}</h3><div class="desk-card" data-action="incoming"><strong>☎ Входящий звонок</strong><small>79000002001 · учебное обращение</small></div>${intakeTasks.map(taskCard).join('')}</section><section class="desk-column"><h3>Подготовка к визиту　${visits.length+appointmentTasks.length}</h3>${visits.map(a=>`<div class="desk-card" data-nav="appointment"><strong>▣ Запись ${h(a.no)}</strong><small>${h(a.date)} ${h(a.time)} · ${h(a.status||'Запланировано')}</small></div>`).join('')}${appointmentTasks.map(taskCard).join('')}</section><section class="desk-column"><h3 class="green">Сделка　${dealTasks.length}</h3>${dealTasks.map(taskCard).join('')}<div class="desk-card" data-nav="estimate"><strong>▤ Калькуляция</strong><small>Подбор работ, товаров и согласование</small></div><div class="desk-card" data-nav="repair"><strong>⚒ Заказ-наряд</strong><small>Работы, товары, материалы заказчика</small></div><div class="desk-card" data-nav="tasks"><strong>☷ Очередь задач CRM</strong><small>Принятие, исполнение и результат</small></div></section></div>`+
 `<p class="tiny-note">Системные события и сроки моделируются кнопками. Тренажёр не отслеживает реальное время в 1С и не создаёт реальные задачи.</p>`;
}
function screenTaskQueue(){const t=crmQueue();return header('Задачи CRM')+
 toolbar(btn('Создать','new:task','Создать пустую задачу CRM.','btn-primary')+btn('Учебное событие: дефектовка','simulateDefect','Это кнопка управления тренажёром, а не подтверждённая команда 1С.','sim-only')+btn('Обновить','refresh','Показать текущее состояние.') )+
 `<div class="list-filter"><label>Поиск:</label><input id="catalogSearch" class="entry" placeholder="Название, документ, ответственный" ${dataHelp('Поиск по задачам','Найдите задачу по тексту или документу.')}><span class="tiny-note">Выделите задачу. Для групповой задачи потребуется принять её к исполнению.</span></div>`+
 table(['Создана','Задача','Ответственный','Предмет','Состояние','Результат'],t.map(x=>trow([h(x.created),h(x.title),h(x.assignee),h(x.reference),h(taskStatusLabel(x)),h(x.result||'')],'taskqueue:'+x.id)),'Учебных задач пока нет')+
 '<p class="tiny-note">Здесь отображаются только записи в браузере. Для перехода откройте строку двойным щелчком.</p>';}
function openCRMTask(id){const t=crmQueue().find(x=>x.id===id);if(!t)return flash('Задача не найдена',true);S.activeTaskId=id;
 if(statusActive(t)&&t.status==='Новая'&&['Приёмка','КО','ОЗЧ'].includes(t.assignee)){
  modal('Задача CRM · приём в работу',`<p><b>${h(t.title)}</b></p><p>Ответственный: группа ${h(t.assignee)}.</p><p>Принять документ к исполнению? После принятия задача будет закреплена за учебным сотрудником.</p>`,btn('Да, принять','acceptCRMTask','Принять документ и изменить ответственного.','btn-primary')+btn('Нет','closeModal','Не изменять ответственное лицо.'));return;
 }
 displayCRMTask(t);
}
function displayCRMTask(t){S.activeTaskId=t.id;S.screen='task';S.v.task={_queueTaskId:t.id,subject:t.reference||t.title,responsible:t.assignee,content:t.content||'',endDate:t.deadline||'',type:t.kind==='phone'?'Телефонный звонок':'Задачи системы',theme:t.kind==='auto_agreement'?'Согласовать КП клиенту по дефектовке':'',result:t.result||''};paint();}
function createDefectEvent(){
 const defectKey='ЗН ТЕСТ-000001';
 const prior=(S.records.autoQuotes||[]).find(q=>q.defectKey===defectKey);
 if(prior){const existing=crmQueue().find(t=>t.kind==='repeat_review'&&t.defectKey===defectKey&&statusActive(t));
  if(!existing)newCRMTask({title:'Ознакомиться с повторной дефектовкой',kind:'repeat_review',assignee:'Приёмка',reference:defectKey,doc:'КП',content:'Проверить дополнение к дефектовке и доработать существующую калькуляцию. Не создавать вторую КП.',defectKey,quoteNo:prior.no});
  setFlag('repeatDefectHandled');paint();flash('Повторная дефектовка: новая калькуляция НЕ создана. Задача на ознакомление добавлена.');return;
 }
 const no='КП-АВТО-00001';
 S.records.autoQuotes=S.records.autoQuotes||[];
 S.records.autoQuotes.push({no,defectKey,vehicle:'КАМАЗ 65115',counterparty:'ООО «Транслогистика»',source:'Автоматическая из Телеграм калькуляция',stage:'Подготовка'});
 S.v.estimate={auto:true,_recordNum:no,source:defectKey,counterparty:'ООО «Транслогистика»',vehicle:'КАМАЗ 65115',agreement:'Договор сервиса № 1',brand:'КАМАЗ',model:'65115',spec:'ДВС КАМАЗ / КПП ZF',reason:'По дефектовке выявлен износ тормозных колодок. Проверить предложенные позиции, нормы и цены. Все наименования учебные.',status:'Подготовка'};
 S.items={works:[{name:'Колодки тормозные - замена',code:'ЦБ00004002',quantity:'1',norm:'',price:'',agreed:false,systemGenerated:true}],parts:[{name:'Колодка тормозная',code:'3501090-01',quantity:'2',price:'',stock:0,agreed:false,systemGenerated:true}]};
 newCRMTask({title:'Подготовить КП клиенту по дефектовке',kind:'auto_prepare',assignee:'Приёмка',reference:no,doc:'КП',content:'Откройте связанную автоматическую КП. Проверьте автоработы, товары, нормочасы, цены и при необходимости отправьте на проценку. Затем переведите КП в статус «Согласование».',defectKey,quoteNo:no});
 setFlag('autoDefectCreated');paint();flash('Системное сообщение смоделировано: создана авто-КП и задача подготовки в группе «Приёмка».');
}
function workflowOnQuoteSave(){const q=v('estimate');if(!q.auto||!q._recordNum)return;
 let prepare=crmQueue().find(t=>t.kind==='auto_prepare'&&t.quoteNo===q._recordNum&&statusActive(t));
 if(q.status==='Согласование'){
  if(prepare){prepare.status='Выполнена';prepare.result='Автоматически закрыта при переходе КП в статус «Согласование»';}
  const exists=crmQueue().find(t=>t.kind==='auto_agreement'&&t.quoteNo===q._recordNum);
  if(!exists)newCRMTask({title:'Согласовать КП клиенту по дефектовке',kind:'auto_agreement',assignee:'Приёмка',reference:q._recordNum,doc:'КП',content:'Связаться с клиентом, зафиксировать согласованные и рекомендованные позиции, изменить статус КП по результату и записать результат разговора.',quoteNo:q._recordNum});
  setFlag('autoAgreementCreated');
 }
}
function pricingHandoff(){const q=v('estimate');if(!q.auto)return;const task=crmQueue().find(t=>t.kind==='auto_prepare'&&t.quoteNo===q._recordNum&&statusActive(t));if(task){task.status='Передано на проценку';task.result='Передана задача в ОЗЧ';}}
function appointmentAnswer(answer){const a=v('appointment');if(!a._recordNum){flash('Сначала сохраните запись на ремонт',true);return}
 let title,kind;
 if(answer==='Подтверждено'){a.status='Подтверждено';flagAppointment();flash('Клиент подтвердил запись (имитация MAX).');paint();return}
 if(answer==='Перенос'){a.status='Требует переноса';title='Согласовать перенос записи на ремонт';kind='appointment_change'}
 else if(answer==='Отменено'){a.status='Отменено';title='Проверить отмену записи на ремонт';kind='appointment_cancel'}
 else{title='Обзвон клиента — нет ответа на подтверждение';kind='appointment_call'}
 flagAppointment();if(!crmQueue().some(t=>t.kind===kind&&t.reference===a._recordNum&&statusActive(t)))newCRMTask({title,kind,assignee:'Приёмка',reference:a._recordNum,doc:'Запись',content:`По записи ${a._recordNum}: ${answer==='Нет ответа'?'нет ответа на запрос подтверждения. Уточнить намерения клиента.':`клиент выбрал «${answer}». Связаться и зафиксировать результат.`}`,deadline:answer==='Нет ответа'?'':new Date(Date.now()+30*60000).toISOString().slice(0,16)});
 setFlag('appointmentResponseHandled');paint();flash('Создана учебная задача приёмке по ответу клиента.');}
function flagAppointment(){const a=v('appointment');const list=S.records.appointments||[];const found=list.find(x=>x.no===a._recordNum);if(found){found.status=a.status;save()}}
