function screenRepair(){const x=v('repair'),top=tab('repairTop','base'),sub=tab('repair','main');const head=header('Заказ-наряд (создание)')+tabs(top,[['base','Основное'],['tree','Дерево документов'],['crm','Регистр События-основания CRM']],'repairTop')+toolbar(btn('Провести и закрыть','save:repair','Проверка и учебное сохранение.','btn-primary')+iconbtn('▣','saveDraft:repair','Сохранить черновик.')+btn('Из КП','importEstimate','Перенести согласованные работы и товары, детали клиента — в материалы заказчика.')+btn('Завершить ремонт','finishRepair','Завершение после внесения результата ремонта.'));
 if(top!=='base')return head+table(['Связанный документ','Состояние'],(S.records.estimates||[]).map(r=>trow([h(r.no||'Калькуляция'),h(r.status||'')])), 'Связанные документы отсутствуют');
 const fields=`<div class="repair-core"><section><div class="kp-green">Клиент</div>${field('repair','counterparty','Заказчик','Выберите контрагента.',{ref:'counterparties'})}${field('repair','agreement','Договор','Договор взаиморасчётов.')}${field('repair','contact','Контактное лицо','Представитель заказчика.',{ref:'contacts'})}<div class="kp-green">Автомобиль</div>${field('repair','vehicle','Автомобиль','Выберите карточку авто.',{ref:'vehicles'})}${field('repair','mileage','Пробег','Запишите фактический пробег.',{type:'number'})}</section><section><div class="kp-green">Описание ремонта</div>${field('repair','type','Вид ремонта','Текущий ремонт, ТО и другие.',{select:['Текущий ремонт','Техническое обслуживание','Гарантия','Кузовной ремонт','Субподряд','Возвратный ремонт','Выездной ремонт ДСТ']})}${field('repair','reason','Причина обращения','Жалоба клиента.')}${field('repair','master','Мастер-приёмщик','Ответственный.',{ref:'groups'})}<div class="kp-green">Выполнение</div>${field('repair','status','Статус','Этап ремонта.',{select:['Открыт','В работе','Закрыт']})}${field('repair','startDate','Дата приёмки','Дата поступления автомобиля.',{type:'date'})}</section></div>`;
 const tabsHtml=subtabs(sub,[['main','Основное'],['works','Автоработы'],['parts','Товары'],['materials','Материалы заказчика'],['result','Результат ремонта']],'repair');
 let content='';if(sub==='main')content=fields;else if(sub==='result')content=field('repair','result','Результат ремонта','Укажите выполненные работы и итог.')+btn('Завершить ремонт','finishRepair','Закрыть учебный ЗН после заполнения результата.','btn-primary');else{content=`<div class="sub-toolbar">${btn('⊕ Добавить','repairAdd:'+sub,'Создать пустую строку в выбранной таблице.')}${btn('Из КП','importEstimate','Перенос только согласованных и клиентских позиций.')}${btn('× Удалить','repairRemove:'+sub,'Удалить последнюю строку.')}</div><div class="kp-table-scroll">${table(['N','Наименование','Количество',sub==='works'?'Нормочасы':'Цена','Код'],repairRows(sub),'Позиции отсутствуют')}</div>`}
 return head+tabsHtml+content+`<div class="kp-bottom-note">Согласованные позиции из КП переносятся в «Автоработы» и «Товары», детали клиента — в «Материалы заказчика». Рекомендации отдельно остаются в карточке авто.</div>`;
}

