function screenBlocked(){const x=v('blocked');return header('Заказ-наряд · разблокировка контрагента (учебный документ)')+
 tabs('blockedTab',[['main','Основное'],['goods','Товары'],['extra','Дополнительно'],['unlock','Разблокировка'],['payment','Оплата']],'blocked')+
 toolbar(btn('Записать','blockedWarn','Проверка блокировки имитирует предупреждение настоящей 1С.','btn-primary')+btn('Проверить блокировку','blockedWarn','Открыть предупреждение с вариантами «Да», «Нет», «Отмена».')+btn('↻ Обновить','refresh','Обновить данные учебного документа.'))+
 info('Финансовая блокировка: работа с документом ограничена до согласования. Данные учебные, реальных запросов не создаётся.','bad')+
 '<div class="form-grid"><div>'+field('blocked','counterparty','Контрагент','Выберите учебного контрагента, по которому нужен запрос.',{ref:'counterparties'})+field('blocked','reason','Причина блокировки','Справочное основание ограничения.',{select:['Просрочка оплаты','Превышен лимит договора','Финансовая блокировка','Прекращение деятельности']})+'</div><div>'+field('blocked','sum','Сумма документа','Ориентировочная сумма для согласования, в учебной валюте.',{type:'number'})+field('blocked','comment','Комментарий автора','Опишите причину необходимости разблокировки.',{area:true})+'</div></div>'+
 subtabs('unlock',[['unlock','Разблокировка']],'blockedContent')+
 '<div class="sub-toolbar">'+btn('⊕ Добавить','blockedAddRow','Добавить строку запроса на согласование.')+btn('▶ Отправить на согласование','sendBlocked','Сформировать учебный запрос на согласование.','btn-primary')+'</div>'+
 table(['Контрагент','Дата запроса','Причина','Сумма документа','Комментарий автора'],flag('blockedRequested')?[trow([h(x.counterparty||''),h(localDate(dateISO(TODAY))),h(x.reason||''),h(x.sum||''),h(x.comment||'')])]:[],'Запросов нет. Добавьте строку или используйте предупреждение при записи.')+
 (flag('blockedRequested')?info('Запрос отправлен на учебное согласование.','good'):'')+(flag('blockedApproved')?info('Разблокировка согласована (имитация). Можно продолжать работу с документом.','good'):'')+
 '<div class="sub-toolbar">'+btn('Смоделировать решение','approveBlocked','В реальной 1С решение приходит через уведомление, в тренажёре моделируется. ')+'</div>';
}
function screenEmail(){return header('Исходящее письмо (создание)')+toolbar(btn('Отправить','sendEmail','Отправить учебное письмо без внешней доставки.','btn-primary')+btn('Выбор формата','chooseEmailFormat','Для отправки печатной формы обычно выбирается PDF.')+btn('Добавить вложение','attachEmail','Добавить учебную печатную форму КП / ЗН.'))+'<div style="max-width:860px">'+field('email','sender','Отправитель','В рабочей 1С отправитель настраивается автоматически.')+field('email','recipient','Получатель','Email клиента; в реальной 1С может подставляться из его карточки.')+field('email','subject','Тема','Тема письма должна однозначно связывать ответ со сделкой.')+field('email','attachment','Вложение','Проверьте наличие и формат прикладываемого документа.')+'<div class="group-label">Текст письма:</div>'+area('email','body','Объясните клиенту содержание направленного документа и ожидаемое действие.',6)+'</div>'+(flag('emailSimulated')?info('Учебное письмо записано в истории. Настоящей отправки не было.','good'):'')}
function screenAppointment(){const x=v('appointment'),section=tab('appointment','base'),stored=S.records.appointments||[];
 const head=header(x._recordNum?'Запись на ремонт '+x._recordNum:'Запись на ремонт (создание)')+tabs(section,[['base','Основное'],['history','Записи на ремонт'],['tree','Дерево документов']],'appointment')+
 toolbar(btn('Записать и закрыть','save:appointment','Записать учебную заявку на ремонт после заполнения обязательных полей.','btn-primary')+iconbtn('▣','saveDraft:appointment','Сохранить черновик.')+btn('Создать ЗН','appointmentToRepair','Перенести данные записи в новый учебный заказ-наряд.')+btn('Проверить заполнение','validateAppointment','Проверить обязательные реквизиты без проведения.')+btn('Учебный ответ клиента ▾','appointmentAnswer','Ручной запуск имитации сообщения MAX. Не является командой реальной 1С.','sim-only')+btn('Ещё ▾','more:appointment','Дополнительные команды учебной формы.'));
 if(section==='history')return head+table(['Номер','Дата','Время','Контактное лицо','Автомобиль','Статус'],stored.map((r,i)=>trow([h(r.no),h(r.date),h(r.time),h(r.contact),h(r.vehicle),h(r.status||'Запланировано')],'savedappointment:'+i)), 'Записей пока нет — создайте первую запись на ремонт.')+`<p class="kp-line-guidance">Двойной щелчок по сохранённой записи откроет её учебную карточку.</p>`;
 if(section==='tree')return head+table(['Основание','Состояние'],[...(x.source?[trow([h(x.source),'Событие'])]:[]),...(flag('appointmentContinued')?[trow(['Заказ-наряд','Создан учебный ЗН'])]:[])], 'Документов-оснований пока нет.');
 return head+`<div class="appointment-form"><div class="appointment-banner"><strong>Запись на ремонт</strong><span>Укажите согласованные с клиентом дату и время визита. Данные учебные, запись не передаётся на станцию.</span></div>
 <div class="appointment-columns"><section><div class="kp-green">Клиент</div>
 ${field('appointment','counterparty','Контрагент','Выберите организацию, от имени которой обращается клиент.',{ref:'counterparties'})}
 ${field('appointment','contact','Контактное лицо','Контакт клиента, согласовавшего визит.',{ref:'contacts'})}
 ${field('appointment','phone','Телефон','Номер для подтверждения записи.')}
 ${field('appointment','agreement','Договор','Договор клиента при наличии.')}
 <div class="kp-green">Автомобиль</div>
 ${field('appointment','vehicle','Автомобиль','Выберите ранее созданную карточку автомобиля.',{ref:'vehicles'})}
 ${field('appointment','mileage','Пробег','Укажите пробег, если его сообщил клиент.',{type:'number'})}
 </section><section><div class="kp-green">Время посещения</div>
 ${field('appointment','date','Дата визита','Дата, которую согласовал клиент.',{type:'date'})}
 ${field('appointment','time','Время визита','Укажите точное время визита.',{type:'time'})}
 ${field('appointment','duration','Планируемый срок, дней','Ориентировочный срок работ, если известен.',{type:'number'})}
 <div class="kp-green">Организация визита</div>
 ${field('appointment','servicePoint','Подразделение','Пункт обслуживания, если известен.',{ref:'groups'})}
 ${field('appointment','responsible','Ответственный','Мастер или группа, которая будет принимать автомобиль.',{ref:'groups'})}
 ${field('appointment','status','Состояние','Статус учебной записи.',{select:['Запланировано','Подтверждено','Требует переноса','Отменено']})}
 </section></div>
 <div class="kp-green">Причина обращения и договорённости</div>
 ${area('appointment','reason','Самостоятельно опишите необходимые работы или жалобу клиента.',5)}
 <div class="appointment-foot"><span>Основание: ${h(x.source||'не указано')}</span><span>Данные сохраняются локально в браузере</span></div>
 <div class="kp-green">Ранее созданные учебные записи</div>
 ${table(['Номер','Дата и время','Контактное лицо','Автомобиль','Статус'],stored.map((r,i)=>trow([h(r.no),h(r.date+' '+r.time),h(r.contact),h(r.vehicle),h(r.status||'Запланировано')],'savedappointment:'+i)),'Записей пока нет')}
 </div>`;
}

function screenProgress(){return header('Журнал обучения')+toolbar(btn('Выгрузить CSV','exportProgress','Скачать журнал прохождения сценариев.')+btn('Сбросить прогресс','resetProgress','Очистить журнал учебных сценариев без удаления введённых карточек.'))+info('Результаты сохраняются только в браузере этого устройства. Без серверной базы они не используются для официальной аттестации.')+table(['Дата','Сценарий','Результат'],S.history.map(r=>trow([h(r.date),h(r.name),h(r.result)])),'Пока нет записей о завершённых сценариях.')}
