function trackCompletion(){let s=SCENARIOS.find(x=>x.id===S.scenario);if(!s)return;let all=s.steps.every(x=>x.test());if(all&&!flag('scenarioDone:'+S.mode+':'+s.id)){S.flags['scenarioDone:'+S.mode+':'+s.id]=true;S.history.push({date:stamp(),name:s.title,result:S.mode==='exam'?'Экзамен: '+Math.max(0,100-(S.examMistakes||0)*10)+' баллов, ошибок '+(S.examMistakes||0):'Обучение: выполнено'});save();flash('Сценарий «'+s.title+'» пройден!')}refreshGuide()}
function clearNew(doc){if(doc==='task')S.activeTaskId=null;S.openRecord=null;S.v[doc]=fresh().v[doc]||{};S.flags['saved:'+doc]=false;if(doc==='estimate')S.items={works:[],parts:[]};paint()}
function vehicleModelsByBrand(brand){const known={КАМАЗ:['65115','5490'],МАЗ:['5440'],УРАЛ:['4320'],VOLVO:['FM 4']};return known[brand]||[]}
function vehicleRenderModels(brand){const holder=document.getElementById('vehicleModelRows');if(!holder)return;document.getElementById('vehicleModelChoice').value='';document.getElementById('vehicleModelText').textContent='не выбрана';holder.innerHTML=vehicleModelsByBrand(brand).map((m,i)=>'<tr data-vehicle-model="'+h(m)+'" tabindex="0"><td>□</td><td>'+String(i+1).padStart(7,'0')+'</td><td>'+h(m)+'</td></tr>').join('')||'<tr><td colspan="3" class="tiny-note">Выберите марку в соседнем списке</td></tr>'}
function highlightVehicleRows(){const map=[['Brand','brand'],['Model','model'],['Spec','spec']];for(const [a,b] of map){const value=document.getElementById('vehicle'+a+'Choice')?.value||'';document.querySelectorAll('[data-vehicle-'+b+']').forEach(row=>{const picked=row.dataset['vehicle'+a]===value;row.classList.toggle('chosen',picked);const cell=row.querySelector('td');if(cell)cell.textContent=picked?'☑':'□'})}}
function openListRecord(doc,id){const ds=doc==='counterparty'?'counterparties':'vehicles',r=(datasets[ds]||[]).concat(S.records[ds]||[]).find(x=>x.id===id);if(!r){flash('Выберите запись из списка',true);return}S.openRecord={doc,id};if(doc==='counterparty')S.v.counterparty={form:r.form||'Юридическое лицо',name:r.name||'',fullName:r.name||'',inn:r.inn||'',kpp:r.kpp||'',code:r.id||''};else S.v.vehicle={name:r.name||'',fullName:r.name||'',vin:r.vin||'',plate:r.plate||'',brand:r.brand||'',model:r.model||'',spec:r.spec||'',owner:r.client||''};go(doc);flash('Открыта существующая учебная карточка: '+r.name)}
