 if(t.dataset.vehicleSpec){document.getElementById('vehicleSpecChoice').value=t.dataset.vehicleSpec;document.getElementById('vehicleSpecText').textContent=t.dataset.vehicleSpec;highlightVehicleRows();return}

 if(t.id==='viewSwitch'){S.only1c=!S.only1c;document.getElementById('app').classList.remove('drawer-left','drawer-right');paint();return}
 if(t.id==='modeSwitch'){const newMode=S.mode==='exam'?'learning':'exam';if(S.scenarioStarted&&!confirm('Переключить режим? Текущее задание будет остановлено.'))return;S.mode=newMode;S.scenario=null;S.scenarioStarted=false;S.examMistakes=0;S.helpCount=0;if(tooltip)tooltip.style.display='none';document.getElementById('app').classList.remove('drawer-left','drawer-right');paint();flash(newMode==='exam'?'Режим экзамена: подсказки отключены. Выберите задание.':'Режим обучения: подсказки доступны.');return}
 if(t.id==='showInfo'){if(S.mode==='exam'){flash('На экзамене подсказки отключены',true);return}document.getElementById('app').classList.toggle('drawer-right');document.getElementById('app').classList.remove('drawer-left');return}
 if(t.id==='toggleTutor'){document.getElementById('app').classList.toggle('drawer-left');document.getElementById('app').classList.remove('drawer-right');return}
 if(t.id==='ribbonHelp'){if(S.mode==='exam')return;document.getElementById('app').classList.add('drawer-right');document.getElementById('startHelp').click();return}
 if(t.id==='leftClose'){document.getElementById('app').classList.remove('drawer-left');return}
 if(t.id==='rightClose'){document.getElementById('app').classList.remove('drawer-right');return} 

 if(t.dataset.scenario){startScenario(t.dataset.scenario);return}
 if(t.dataset.nav){go(t.dataset.nav);return}
 if(t.dataset.tab){let [group,id]=t.dataset.tab.split('.');S.activeTab[group]=id;paint();return}
 if(t.dataset.choose){chooseRecord(t.dataset.choose,t.dataset.target);return}
 if(t.dataset.clear){setValue(t.dataset.clear,'');paint();return}
 if(t.dataset.row){let parts=t.dataset.row.split(':');if(parts[0]==='taskqueue'){doAction('openQueueTask:'+parts[1]);return}if(parts[0]==='savedappointment'){doAction('openAppointment:'+parts[1]);return}if(parts[0]==='pick'){if(window._pick){window._pick.selected=parts[2];const all=document.getElementById('pickerRows');all?.querySelectorAll('tr').forEach(tr=>tr.classList.toggle('selected',tr===t));}return}if(parts[0]==='lookup'){doAction('lookup:'+parts[1]);return}if(parts[0]==='row'){S.selectedRow={doc:parts[1],id:parts[2]};t.closest('table')?.querySelectorAll('tr').forEach(tr=>tr.classList.toggle('selected',tr===t));save();return}}
 if(t.dataset.action){doAction(t.dataset.action,t);return}
 if(t.id==='resetAll'){if(confirm('Сбросить все учебные данные в этом браузере?')){S=fresh();paint();flash('Учебная база сброшена')}return}
 if(t.id==='tabReset'){go('desktop');return}
 if(t.id==='startHelp'){if(S.mode==='exam')return;S.helpCount=(S.helpCount||0)+1;let sc=SCENARIOS.find(x=>x.id===S.scenario),z=sc?.steps[S.step];showHelp(z?.desc||z?.label||'Выберите учебный сценарий в левой панели.',z?.label||'Следующий шаг');let sel=HIGHLIGHT_TARGETS[sc?.id]?.[S.step];let el=sel?document.querySelector(sel):null;if(el){el.scrollIntoView({block:'center',behavior:'smooth'});el.classList.add('spotlight');setTimeout(()=>el.classList.remove('spotlight'),2400)}else if(sc)flash('Откройте нужную вкладку или документ, затем повторите подсказку');return}
 if(t.id==='stopScenario'){S.scenario=null;S.scenarioStarted=false;refreshGuide();return}
